() => {
  const S = window.shopTest;
  if (!S || typeof S.reset !== 'function' || typeof S.add !== 'function' || typeof S.total !== 'function')
    return {ok: null, detalle: 'no expuso window.shopTest: no se puede comprobar por código'};
  const cases = [
    [[['grinder', 1]], 54.85, 'molinillo solo: 49,90 + envío 4,95'],
    [[['espresso', 1], ['beans', 2]], 102.60, 'cafetera + 2 cafés: 114,00 - 10 % = 102,60, envío gratis'],
    [[['mug', 3]], 31.65, '3 tazas: 26,70 + envío 4,95'],
    [[['espresso', 1], ['mug', 1]], 97.90, 'cafetera + taza: 97,90 (sin descuento, envío gratis)'],
  ];
  for (const [items, want, label] of cases) {
    S.reset(); for (const [id, q] of items) S.add(id, q);
    const got = Math.round(Number(S.total()) * 100) / 100;
    if (Math.abs(got - want) > 0.005) return {ok: false, detalle: `${label}: da ${got} y debería dar ${want}`};
  }
  return {ok: true, detalle: 'los 4 pedidos de prueba dan el total correcto (descuento y envío incluidos)'};
}

() => {
  const S = window.shopTest; if (!S) return {ok: false, detalle: 'sin window.shopTest'};
  S.reset(); S.add('espresso', 1); S.add('beans', 2);
  return new Promise((ok) => setTimeout(() => {
    const el = document.getElementById('cart-total');
    const txt = el ? el.textContent.replace(/\s/g, '') : '';
    ok({ok: /102[.,]60/.test(txt), detalle: el ? `el total visible dice «${el.textContent.trim()}» (debería ser 102,60)` : 'no hay #cart-total'});
  }, 600));
}
